import{_ as i,c as t,o,ag as e,j as r}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"安裝","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/installation.md","filePath":"zh-TW/guide/installation.md","lastUpdated":1794112334000}'),l={name:"zh-TW/guide/installation.md"};function n(s,a,h,c,d,p){return o(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to &quot;安裝&quot;">​</a></h1><h2 id="下載-nicasa" tabindex="-1">下載 Nicasa <a class="header-anchor" href="#下載-nicasa" aria-label="Permalink to &quot;下載 Nicasa&quot;">​</a></h2><p>Nicasa 僅透過 Mac App Store 提供 macOS 版本。應用程式售價 $4.99，一次性購買即可解鎖全部功能。</p><h3 id="下載方式" tabindex="-1">下載方式 <a class="header-anchor" href="#下載方式" aria-label="Permalink to &quot;下載方式&quot;">​</a></h3><ul><li><strong>Mac App Store</strong>：<a href="https://apps.apple.com/us/app/nicasa-image-viewer/id6756032669?mt=12" target="_blank" rel="noreferrer">下載 Nicasa</a> —— $4.99</li><li><strong>Chrome 擴充功能</strong>：<a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">免費 Chrome 擴充功能</a> —— 免費</li></ul><h2 id="安裝步驟" tabindex="-1">安裝步驟 <a class="header-anchor" href="#安裝步驟" aria-label="Permalink to &quot;安裝步驟&quot;">​</a></h2><h3 id="透過-mac-app-store-安裝" tabindex="-1">透過 Mac App Store 安裝 <a class="header-anchor" href="#透過-mac-app-store-安裝" aria-label="Permalink to &quot;透過 Mac App Store 安裝&quot;">​</a></h3><ol><li>點擊上面的「下載 Nicasa」連結，或在 Mac App Store 中搜尋「Nicasa」</li><li>點擊「取得」或「購買」完成付費（$4.99）</li><li>應用程式會自動下載並安裝</li><li>從「應用程式」檔案夾或啟動台啟動 Nicasa</li></ol><h3 id="安裝-chrome-擴充功能" tabindex="-1">安裝 Chrome 擴充功能 <a class="header-anchor" href="#安裝-chrome-擴充功能" aria-label="Permalink to &quot;安裝 Chrome 擴充功能&quot;">​</a></h3><ol><li>前往 <a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">Chrome 線上應用程式商店頁面</a></li><li>點擊「加到 Chrome」</li><li>在彈出視窗中確認安裝</li><li>擴充功能即會加入你的瀏覽器</li></ol><h4 id="chrome-擴充功能示範" tabindex="-1">Chrome 擴充功能示範 <a class="header-anchor" href="#chrome-擴充功能示範" aria-label="Permalink to &quot;Chrome 擴充功能示範&quot;">​</a></h4>',11),r("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0"}},[r("iframe",{src:"https://www.youtube.com/embed/NJPweIr1J4s",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:"",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%"}})],-1),e('<p><a href="https://www.youtube.com/watch?v=NJPweIr1J4s" target="_blank" rel="noopener">觀看：Nicasa Chrome 擴充功能快速示範</a></p><h2 id="首次啟動" tabindex="-1">首次啟動 <a class="header-anchor" href="#首次啟動" aria-label="Permalink to &quot;首次啟動&quot;">​</a></h2><p>第一次啟動 Nicasa 時：</p><ol><li>系統會提示你授予必要權限（截圖功能需要螢幕錄製權限）</li><li>應用程式會掃描「圖片」檔案夾中的圖片</li><li>你可以立即開始瀏覽圖庫</li><li>建議安裝 Chrome 擴充功能，以獲得更完整的網頁看圖體驗</li></ol><h3 id="finder-同步擴充功能" tabindex="-1">Finder 同步擴充功能 <a class="header-anchor" href="#finder-同步擴充功能" aria-label="Permalink to &quot;Finder 同步擴充功能&quot;">​</a></h3><p>Nicasa 附帶一個 Finder 工具列擴充功能，用於快速處理圖片：</p><ol><li>啟動 Nicasa 後，進入<strong>系統設定</strong> → <strong>擴充功能</strong> → <strong>Finder 擴充功能</strong></li><li>啟用 <strong>Nicasa Finder Sync</strong></li><li>在 Finder 工具列上按右鍵 → <strong>自訂工具列…</strong></li><li>把 Nicasa 按鈕拖到工具列上</li></ol><p>這樣你就能直接在 Finder 裡對選取的圖片進行最佳化或編輯。</p><h2 id="系統需求" tabindex="-1">系統需求 <a class="header-anchor" href="#系統需求" aria-label="Permalink to &quot;系統需求&quot;">​</a></h2><ul><li><strong>macOS</strong>：10.13 或更高版本</li><li><strong>儲存空間</strong>：54.5 MB 可用空間</li><li><strong>記憶體</strong>：最低 4GB RAM，建議 8GB</li></ul><h2 id="權限" tabindex="-1">權限 <a class="header-anchor" href="#權限" aria-label="Permalink to &quot;權限&quot;">​</a></h2><p>Nicasa 需要以下權限：</p><ul><li><strong>螢幕錄製</strong>：用於截圖功能（可稍後授予）</li><li><strong>輔助使用</strong>：用於懸浮模式相關功能（選用）</li><li><strong>檔案與檔案夾</strong>：存取「圖片」檔案夾及使用者選取的目錄</li></ul><p>你可以隨時在「系統設定 &gt; 隱私權與安全性」中修改這些權限。</p><h2 id="安裝疑難排解" tabindex="-1">安裝疑難排解 <a class="header-anchor" href="#安裝疑難排解" aria-label="Permalink to &quot;安裝疑難排解&quot;">​</a></h2><p>如果安裝過程中遇到問題：</p><ul><li>確認你擁有管理者/root 權限</li><li>檢查系統是否滿足最低需求</li><li>嘗試重新下載安裝檔</li><li>如在 Linux 上安裝，請確認已安裝所需相依套件</li></ul><p>如需更多協助，請前往我們的<a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">問題回報頁</a>。</p>',18)])])}const g=i(l,[["render",n]]);export{u as __pageData,g as default};
